
create schema if not exists museum_private;
revoke all on schema museum_private from public;
grant usage on schema museum_private to authenticated;
create table museum_private.admins(user_id uuid primary key references auth.users(id) on delete cascade);
create function museum_private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from museum_private.admins where user_id=auth.uid()) $$;
revoke all on function museum_private.is_admin() from public;grant execute on function museum_private.is_admin() to authenticated;
create table public.profiles(user_id uuid primary key default auth.uid() references auth.users(id) on delete cascade,full_name text not null default '' check(length(full_name)<=150),created_at timestamptz not null default now());
create table public.products(id text primary key,name text not null,description text not null default '',category text not null,image_path text not null,price_pence integer check(price_pence>=0),stock integer check(stock>=0),active boolean not null default true);
create table public.wishlist(user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,product_id text not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table public.checkout_sessions(token_hash text primary key check(token_hash ~ '^[a-f0-9]{64}$'),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,jotform_submission_id text not null unique,summary text not null,delivery text not null default '',status text not null default 'received' check(status in ('received','confirmed','ready','dispatched','completed','cancelled')),created_at timestamptz not null default now());
create index on public.orders(user_id);
create table public.memberships(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,plan text not null check(plan in ('Individual','Family','Supporter')),status text not null default 'requested' check(status in ('requested','active','expired','cancelled')),expires_on date,created_at timestamptz not null default now());
create index on public.memberships(user_id);
create unique index membership_one_open on public.memberships(user_id) where status in ('requested','active');
create table public.exhibitions(id text primary key,title text not null,description text not null default '',image_path text not null,starts_at timestamptz,capacity integer check(capacity>0),active boolean not null default true);
create table public.bookings(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,exhibition_id text not null references public.exhibitions(id),quantity integer not null check(quantity between 1 and 10),status text not null default 'requested' check(status in ('requested','confirmed','cancelled')),created_at timestamptz not null default now());
create index on public.bookings(user_id);create index on public.bookings(exhibition_id);
create unique index booking_one_open on public.bookings(user_id,exhibition_id) where status in ('requested','confirmed');
create function museum_private.check_capacity() returns trigger language plpgsql set search_path='' as $$
declare cap integer; used integer;
begin
if new.status='confirmed' then
select capacity into cap from public.exhibitions where id=new.exhibition_id for update;
select coalesce(sum(quantity),0) into used from public.bookings where exhibition_id=new.exhibition_id and status='confirmed' and id<>new.id;
if cap is null then raise exception 'Set exhibition capacity before confirming bookings';end if;
if used+new.quantity>cap then raise exception 'Exhibition capacity exceeded';end if;
end if;
return new;
end $$;
create trigger enforce_booking_capacity before insert or update on public.bookings for each row execute function museum_private.check_capacity();
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.wishlist enable row level security;alter table public.checkout_sessions enable row level security;alter table public.orders enable row level security;alter table public.memberships enable row level security;alter table public.exhibitions enable row level security;alter table public.bookings enable row level security;alter table museum_private.admins enable row level security;
create policy profiles_own on public.profiles for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy profiles_admin_read on public.profiles for select to authenticated using((select museum_private.is_admin()));
create policy products_public on public.products for select to anon,authenticated using(active);
create policy products_admin on public.products for all to authenticated using((select museum_private.is_admin())) with check((select museum_private.is_admin()));
create policy wishlist_own on public.wishlist for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy checkout_own_read on public.checkout_sessions for select to authenticated using(user_id=(select auth.uid()));
create policy checkout_own_insert on public.checkout_sessions for insert to authenticated with check(user_id=(select auth.uid()));
create policy orders_own_read on public.orders for select to authenticated using(user_id=(select auth.uid()));
create policy orders_admin on public.orders for all to authenticated using((select museum_private.is_admin())) with check((select museum_private.is_admin()));
create policy memberships_own_read on public.memberships for select to authenticated using(user_id=(select auth.uid()));
create policy memberships_request on public.memberships for insert to authenticated with check(user_id=(select auth.uid()) and status='requested' and expires_on is null);
create policy memberships_admin on public.memberships for all to authenticated using((select museum_private.is_admin())) with check((select museum_private.is_admin()));
create policy exhibitions_public on public.exhibitions for select to anon,authenticated using(active);
create policy exhibitions_admin on public.exhibitions for all to authenticated using((select museum_private.is_admin())) with check((select museum_private.is_admin()));
create policy bookings_own_read on public.bookings for select to authenticated using(user_id=(select auth.uid()));
create policy bookings_request on public.bookings for insert to authenticated with check(user_id=(select auth.uid()) and status='requested' and exists(select 1 from public.exhibitions where id=exhibition_id and active));
create policy bookings_cancel on public.bookings for update to authenticated using(user_id=(select auth.uid()) and status in ('requested','confirmed')) with check(user_id=(select auth.uid()) and status='cancelled');
create policy bookings_admin on public.bookings for all to authenticated using((select museum_private.is_admin())) with check((select museum_private.is_admin()));
grant select on public.products,public.exhibitions to anon;
grant select,insert,update,delete on public.products,public.exhibitions,public.profiles,public.wishlist,public.memberships to authenticated;
grant select,insert on public.checkout_sessions,public.bookings to authenticated;
grant update(status) on public.bookings to authenticated;
grant select on public.orders to authenticated;grant update(status) on public.orders to authenticated;
grant all on public.orders,public.checkout_sessions to service_role;
create function public.museum_admin_status() returns boolean language sql stable security invoker set search_path='' as $$ select museum_private.is_admin() $$;
revoke all on function public.museum_admin_status() from public;grant execute on function public.museum_admin_status() to authenticated;
